// Retrieve the raw JSON response from the preceding CoinGecko HTTP Request node
const rawData = $input.first().json;

// 1. Organize Data
const cryptoMap = {
  'bitcoin': 'Bitcoin (BTC)',
  'ethereum': 'Ethereum (ETH)',
  'arbitrum': 'Arbitrum (ARB)',
  'ondo-finance': 'Ondo (ONDO)'
};

const commodityMap = {
  'pax-gold': 'Gold (PAXG)',
  'kinesis-silver': 'Silver (KAG)',
  'united-states-oil-fund-ondo-tokenized': 'Crude Oil ETF Proxy (USOON)'
};

const organized = {
  crypto: [],
  commodities: [],
  forex: {}
};

// Format helper for currency & percentage
const formatUSD = (num) => num ? `$${Number(num).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` : 'N/A';
const formatChange = (num) => {
  if (num === undefined || num === null) return { text: '0.00%', color: '#666666' };
  const isPositive = num >= 0;
  return {
    text: `${isPositive ? '+' : ''}${Number(num).toFixed(2)}%`,
    color: isPositive ? '#16a34a' : '#dc2626'
  };
};

// Populate Crypto
for (const [id, label] of Object.entries(cryptoMap)) {
  if (rawData[id]) {
    organized.crypto.push({
      name: label,
      price: formatUSD(rawData[id].usd),
      change: formatChange(rawData[id].usd_24h_change)
    });
  }
}

// Populate Commodities
for (const [id, label] of Object.entries(commodityMap)) {
  if (rawData[id]) {
    organized.commodities.push({
      name: label,
      price: formatUSD(rawData[id].usd),
      change: formatChange(rawData[id].usd_24h_change)
    });
  }
}

// Populate USD Forex Rates (including DKK, using Tether as ~1 USD reference)
if (rawData['tether']) {
  organized.forex = {
    'USD / EUR': rawData['tether'].eur?.toFixed(4) || 'N/A',
    'USD / INR': rawData['tether'].inr?.toFixed(2) || 'N/A',
    'USD / GBP': rawData['tether'].gbp?.toFixed(4) || 'N/A',
    'USD / JPY': rawData['tether'].jpy?.toFixed(2) || 'N/A',
    'USD / DKK': rawData['tether'].dkk?.toFixed(4) || 'N/A'
  };
} else if (rawData['bitcoin'] && rawData['bitcoin'].usd) {
  const btcUsd = rawData['bitcoin'].usd;
  organized.forex = {
    'USD / EUR': (rawData['bitcoin'].eur / btcUsd).toFixed(4),
    'USD / INR': (rawData['bitcoin'].inr / btcUsd).toFixed(2),
    'USD / GBP': (rawData['bitcoin'].gbp / btcUsd).toFixed(4),
    'USD / JPY': (rawData['bitcoin'].jpy / btcUsd).toFixed(2),
    'USD / DKK': (rawData['bitcoin'].dkk / btcUsd).toFixed(4)
  };
}

// 2. Build HTML Email Rows
const buildRows = (items) => items.map(item => `
  <tr>
    <td style="padding: 10px 12px; border-bottom: 1px solid #e5e7eb; font-weight: 500; color: #111827;">${item.name}</td>
    <td style="padding: 10px 12px; border-bottom: 1px solid #e5e7eb; text-align: right; color: #111827;">${item.price}</td>
    <td style="padding: 10px 12px; border-bottom: 1px solid #e5e7eb; text-align: right; font-weight: 600; color: ${item.change.color};">${item.change.text}</td>
  </tr>
`).join('');

const forexRows = Object.entries(organized.forex).map(([pair, rate]) => `
  <tr>
    <td style="padding: 8px 12px; border-bottom: 1px solid #e5e7eb; color: #374151;">${pair}</td>
    <td style="padding: 8px 12px; border-bottom: 1px solid #e5e7eb; text-align: right; font-weight: 600; color: #111827;">${rate}</td>
  </tr>
`).join('');

// 3. Assemble Full HTML Template
const dateStr = new Date().toLocaleDateString('en-US', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric' });

const htmlEmail = `
<div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px; background-color: #f9fafb;">
  <div style="background-color: #ffffff; border-radius: 8px; padding: 24px; border: 1px solid #e5e7eb;">
    <h2 style="margin: 0 0 4px 0; color: #111827; font-size: 20px;">Market Snapshot</h2>
    <p style="margin: 0 0 20px 0; color: #6b7280; font-size: 13px;">${dateStr} • Source: CoinGecko</p>

    <!-- Crypto Section -->
    <h3 style="margin: 20px 0 8px 0; font-size: 14px; text-transform: uppercase; letter-spacing: 0.05em; color: #4b5563;">Crypto</h3>
    <table style="width: 100%; border-collapse: collapse; font-size: 14px;">
      <thead>
        <tr style="background-color: #f3f4f6; color: #6b7280; font-size: 12px; text-transform: uppercase;">
          <th style="padding: 8px 12px; text-align: left;">Asset</th>
          <th style="padding: 8px 12px; text-align: right;">Price (USD)</th>
          <th style="padding: 8px 12px; text-align: right;">24h Change</th>
        </tr>
      </thead>
      <tbody>
        ${buildRows(organized.crypto)}
      </tbody>
    </table>

    <!-- Commodities Section -->
    <h3 style="margin: 24px 0 8px 0; font-size: 14px; text-transform: uppercase; letter-spacing: 0.05em; color: #4b5563;">Commodities (Tokenized)</h3>
    <table style="width: 100%; border-collapse: collapse; font-size: 14px;">
      <thead>
        <tr style="background-color: #f3f4f6; color: #6b7280; font-size: 12px; text-transform: uppercase;">
          <th style="padding: 8px 12px; text-align: left;">Asset</th>
          <th style="padding: 8px 12px; text-align: right;">Price (USD)</th>
          <th style="padding: 8px 12px; text-align: right;">24h Change</th>
        </tr>
      </thead>
      <tbody>
        ${buildRows(organized.commodities)}
      </tbody>
    </table>

    <!-- Forex Section -->
    <h3 style="margin: 24px 0 8px 0; font-size: 14px; text-transform: uppercase; letter-spacing: 0.05em; color: #4b5563;">USD Exchange Rates</h3>
    <table style="width: 100%; border-collapse: collapse; font-size: 14px;">
      <tbody>
        ${forexRows}
      </tbody>
    </table>
  </div>
</div>
`;

// 4. Plain Text Fallback
const textEmail = `Market Snapshot (${dateStr})\n\n` +
  `CRYPTO:\n` + organized.crypto.map(c => `- ${c.name}: ${c.price} (${c.change.text})`).join('\n') + `\n\n` +
  `COMMODITIES:\n` + organized.commodities.map(c => `- ${c.name}: ${c.price} (${c.change.text})`).join('\n') + `\n\n` +
  `FOREX:\n` + Object.entries(organized.forex).map(([k, v]) => `- ${k}: ${v}`).join('\n');

return [
  {
    json: {
      subject: `Daily Market Prices - ${dateStr}`,
      html: htmlEmail,
      text: textEmail,
      rawOrganized: organized
    }
  }
];
